DROP TABLE IF EXISTS `audit_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_results` (
  `id` int NOT NULL AUTO_INCREMENT,
  `host_id` int NOT NULL,
  `code` varchar(20) NOT NULL,
  `category` varchar(50) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `importance` varchar(50) DEFAULT NULL,
  `weight_score` int DEFAULT '0',
  `risk_score` int DEFAULT '0',
  `status` varchar(20) NOT NULL,
  `target_file` varchar(255) DEFAULT NULL,
  `command` text,
  `command_output` text,
  `evidence_description` text,
  `recommendation_text` text,
  `remediation_cmd` text,
  `reviewed` tinyint(1) DEFAULT '0',
  `fixed_by_user` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `manual_verdict` varchar(10) NOT NULL DEFAULT '',
  `manual_reason` text,
  `manual_by` bigint unsigned DEFAULT NULL,
  `manual_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `host_id` (`host_id`),
  CONSTRAINT `audit_results_ibfk_1` FOREIGN KEY (`host_id`) REFERENCES `audit_hosts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=136590 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

